import type { Metadata } from "next";
import type { Resort } from "@/types/resort";
import {
  Locale,
  defaultLocale,
  getTranslator,
  locales,
} from "@/src/i18n/translations";
import { formatCad } from "@/src/i18n/format";
import { intlLocale, localizePath, ogLocale } from "@/src/i18n/routing";

// Route generated by src/app/opengraph-image.tsx; used when a page has no image of its own.
export const DEFAULT_OG_IMAGE = "/opengraph-image";

export function getSiteUrl() {
  if (process.env.NEXT_PUBLIC_SITE_URL) return process.env.NEXT_PUBLIC_SITE_URL;
  if (process.env.VERCEL_PROJECT_PRODUCTION_URL) {
    return `https://${process.env.VERCEL_PROJECT_PRODUCTION_URL}`;
  }
  return "http://localhost:3000";
}

export function absoluteUrl(path: string) {
  return new URL(path, getSiteUrl()).toString();
}

// Unset → no email is shown anywhere. A placeholder address is worse than none.
export function getSupportEmail() {
  return process.env.NEXT_PUBLIC_SUPPORT_EMAIL?.trim() || undefined;
}

// Child pages that define `openGraph` replace the root block entirely, so they
// spread this to keep site-wide fields.
export function openGraphBase(locale: Locale) {
  return {
    siteName: getTranslator(locale)("appName"),
    locale: ogLocale[locale],
    alternateLocale: locales
      .filter((other) => other !== locale)
      .map((other) => ogLocale[other]),
  } satisfies Metadata["openGraph"];
}

// Reciprocal hreflang set for a path. `resolve` lets the sitemap make them absolute.
export function languageAlternates(
  path: string,
  resolve: (path: string) => string = (value) => value,
) {
  return {
    "en-CA": resolve(localizePath(path, "en")),
    "fr-CA": resolve(localizePath(path, "fr")),
    es: resolve(localizePath(path, "es")),
    "x-default": resolve(localizePath(path, defaultLocale)),
  };
}

// Pages whose main content is translated: self-referencing canonical + hreflang.
export function localizedAlternates(
  path: string,
  locale: Locale,
): Metadata["alternates"] {
  return {
    canonical: localizePath(path, locale),
    languages: languageAlternates(path),
  };
}

// Pages whose main content exists in English only (blog, legal): the localized
// copies canonicalize to the English URL and carry no hreflang.
export function englishOnlyAlternates(path: string): Metadata["alternates"] {
  return { canonical: localizePath(path, defaultLocale) };
}

export function resortTitle(resort: Resort, locale: Locale) {
  return /\b(ski|resort|hill|club)\b/i.test(resort.name)
    ? resort.name
    : getTranslator(locale)("metaResortTitle", { name: resort.name });
}

export function resortDescription(resort: Resort, locale: Locale) {
  const t = getTranslator(locale);
  const money = (amount: number) => formatCad(amount, locale);
  const lower = (key: string) => t(key).toLocaleLowerCase(intlLocale[locale]);

  const place = [resort.region, resort.country].filter(Boolean).join(", ");
  const prices = [
    resort.dayTicketPrice > 0 &&
      t("metaLiftFrom", { price: money(resort.dayTicketPrice) }),
    resort.skiRentalPrice > 0 &&
      t("metaSkiRental", { price: money(resort.skiRentalPrice) }),
    resort.snowBoardRentalPrice > 0 &&
      t("metaSnowboardRental", { price: money(resort.snowBoardRentalPrice) }),
  ].filter(Boolean);
  const runs: [number, string][] = [
    [resort.runs.green, lower("green")],
    [resort.runs.blue, lower("blue")],
    [resort.runs.black, lower("black")],
    [resort.runs.doubleBlack, lower("doubleBlack")],
  ];
  const openRuns = runs.filter(([count]) => count > 0);
  const totalRuns = openRuns.reduce((sum, [count]) => sum + count, 0);

  return [
    `${resort.name}${place ? ` (${place})` : ""}${prices.length ? `: ${prices.join(", ")}` : ""}.`,
    totalRuns > 0 &&
      `${t(totalRuns === 1 ? "metaRun" : "metaRuns", { count: totalRuns })}: ${openRuns.map(([count, label]) => `${count} ${label}`).join(", ")}.`,
    t("metaTail"),
  ]
    .filter(Boolean)
    .join(" ");
}
